import json,base64,pathlib
r=pathlib.Path(__file__).parent
m=json.loads((r/'artifacts/metrics.json').read_text())
img=base64.b64encode((r/'artifacts/rollout_comparison.png').read_bytes()).decode()
from html import escape
rows=''.join(f'<tr><td>{h} steps</td><td>{d["closed_loop_mse"]:.5f}</td><td>{d["frozen_first_frame_mse"]:.5f}</td><td>{d["changed_region_mse"]:.5f}</td></tr>' for h,d in m['rollout'].items())
js=json.dumps(m)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>EchoWorld v4 | Latent World Model Lab</title><style>:root{font-family:Inter,system-ui,Segoe UI,sans-serif;color:#e7eef9;background:#0a1220}*{box-sizing:border-box}body{margin:0}main{max-width:1090px;margin:0 auto;padding:32px 20px 70px}header{border-bottom:1px solid #28364b;padding-bottom:22px}h1{font-size:clamp(26px,4vw,44px);margin:5px 0}p{color:#b1c1d6;line-height:1.6}.sub{font-size:13px;letter-spacing:.12em;color:#68dcb5;text-transform:uppercase}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:22px 0}.card,section{background:#132036;border:1px solid #2a3950;border-radius:15px;padding:20px;margin:14px 0}.val{font-size:29px;font-weight:700;margin-top:7px}.warn{color:#ffd08a}.good{color:#75dfb6}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid #344359;font-size:14px}th{color:#a4b7d0}img{width:100%;image-rendering:pixelated;border-radius:10px}button{background:#264461;border:1px solid #52759a;color:white;border-radius:9px;padding:9px 14px;cursor:pointer}button.active{background:#2eab8a;color:#071e1c}.bars{display:flex;gap:4px;height:240px;align-items:end;padding:10px 0}.barcol{flex:1;text-align:center;color:#9caec4;font-size:12px}.bar{border-radius:6px 6px 0 0;background:#35b89c;min-height:3px}.bar.baseline{background:#e5ad71}.legend{display:flex;gap:16px;color:#b8c7d9;font-size:13px}.dot{display:inline-block;width:10px;height:10px;border-radius:2px;background:#35b89c}.dot.base{background:#e5ad71}code{color:#9ee6ce}a{color:#88dcff}.small{font-size:13px;color:#b3c4d9}</style><main><header><div class="sub">EchoWorld · World Model Research · v4.0.0</div><h1>Action-conditioned Latent World Model</h1><p>Encoder → 8×8 latent grid → convolutional recurrent dynamics conditioned on player actions → Decoder. Independently generated test episodes. Experimental results, not Genie 4 reproduction.</p></header><div class="grid"><div class="card"><div class="small">Training transitions</div><div class="val">1500</div></div><div class="card"><div class="small">Latent representation</div><div class="val">12 × 8 × 8</div></div><div class="card"><div class="small">Independent test episodes</div><div class="val">12</div></div><div class="card"><div class="small">Epochs / seed</div><div class="val">5 / 2026</div></div></div><section><h2>Closed-loop prediction vs frozen-first-frame baseline</h2><p>Each model-generated frame is fed back into the model. The baseline reuses the initial frame from t=0 for the whole horizon. Lower is better; this is deliberately a weak but necessary visual baseline.</p><div class="bars" id="bars"></div><div class="legend"><span><i class="dot"></i> Learned rollout</span><span><i class="dot base"></i> Frozen initial frame</span></div><table><thead><tr><th>Horizon</th><th>Learned MSE ↓</th><th>Frozen frame MSE ↓</th><th>Changed-region MSE ↓</th></tr></thead><tbody>'''+rows+'''</tbody></table><p class="warn">Important: The v4 model is worse than baseline at 1 and 10 steps. This experiment is not evidence of reliable generative world simulation.</p></section><section><h2>Visual rollout: ground truth vs learned prediction</h2><p>Top: simulator ground truth. Bottom: autoregressive model predictions. Columns are frames t=0, 1, 3, 10, 25 and 50. Scene is 32×32 RGB, enlarged for inspection.</p><img alt="Two-row image showing 6 frames of real and learned worlds" src="data:image/png;base64,'''+img+'''"/><p class="small">Objects and color boundaries can drift. No direct pixel-level supervision at test time after the first input.</p></section><section><h2>Training progression</h2><div id="learning"></div></section><section><h2>Reproducibility / technical scope</h2><p>Code and weights in <code>src/v4.py</code> and <code>artifacts/v4_latent_world_model.pt</code>. Training data is generated by the original EchoWorld rule-based simulator. No Google model weights, production world model API, audio generation, or unsupervised latent-action discovery.</p><p><a href="https://deepmind.google/research/publications/60474/">Genie (2024)</a> · <a href="https://deepmind.google/blog/genie-2-a-large-scale-foundation-world-model/">Genie 2</a> · <a href="https://deepmind.google/blog/genie-4-a-new-generation-of-world-simulation/">Genie 4</a></p></section></main><script>const metrics='''+js+''';const b=document.getElementById('bars');for(const [h,d] of Object.entries(metrics.rollout)){for(const [key,cls] of [['closed_loop_mse',''],['frozen_first_frame_mse','baseline']]){let x=document.createElement('div');x.className='barcol';x.innerHTML='<div class="bar '+cls+'" style="height:'+(d[key]/0.03*185)+'px" title="'+d[key].toFixed(5)+'"></div><div>'+h+' '+(cls?'Baseline':'Model')+'</div>';b.appendChild(x)}}document.getElementById('learning').innerHTML='<table><thead><tr><th>Epoch</th><th>Training loss</th><th>1-step rollout MSE</th></tr></thead><tbody>'+metrics.history.map(x=>'<tr><td>'+x.epoch+'</td><td>'+x.train_loss.toFixed(5)+'</td><td>'+x.test_rollout_1_mse.toFixed(5)+'</td></tr>').join('')+'</tbody></table>';</script></html>'''
(r/'index.html').write_text(html)
print('Created',r/'index.html')
